def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 0 or (sr, sc) in seen:
                continue

            stack = [(sr, sc)]
            seen.add((sr, sc))
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] != 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            top = min(r for r, c in cells)
            bottom = max(r for r, c in cells)
            left = min(c for r, c in cells)
            right = max(c for r, c in cells)

            layers = []
            while top <= bottom and left <= right:
                perimeter = []
                for r in range(top, bottom + 1):
                    for c in range(left, right + 1):
                        if r in (top, bottom) or c in (left, right):
                            perimeter.append(grid[r][c])

                if not perimeter:
                    break
                color = max(set(perimeter), key=perimeter.count)
                if not layers or layers[-1] != color:
                    layers.append(color)

                top += 1
                bottom -= 1
                left += 1
                right -= 1

            color_map = {old: new for old, new in zip(layers, reversed(layers))}
            for r, c in cells:
                out[r][c] = color_map.get(grid[r][c], grid[r][c])

    return out
